package com.bank.activity;

import java.util.Arrays;
import java.util.logging.Logger;

// Orders transaction references for National Bank of India activity screens.
public class ActivityService {
    private static final Logger log = Logger.getLogger(ActivityService.class.getName());

    // Reverses the array IN PLACE (mutates the caller's array). O(n), O(1) space.
    public void reverseInPlace(String[] txns) {
        if (txns == null) return;
        int left = 0;
        int right = txns.length - 1;
        while (left < right) {                 // stop when pointers meet
            String temp = txns[left];          // swap the two ends
            txns[left] = txns[right];
            txns[right] = temp;
            left++;                            // step inward
            right--;
        }
        log.fine(() -> "Reversed in place: " + Arrays.toString(txns));
    }

    // Returns a reversed COPY; the original array is left untouched.
    public String[] reversedCopy(String[] txns) {
        if (txns == null) return null;
        String[] copy = Arrays.copyOf(txns, txns.length);
        reverseInPlace(copy);                  // reverse the copy, not the original
        return copy;
    }
}
