package com.bank.activity;

import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: newest-first display and untouched audit copy.
public class ActivityDemo {
    private static final Logger log = Logger.getLogger(ActivityDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        ActivityService service = new ActivityService();

        // Rajesh (SAV2001) transaction references, oldest first.
        String[] chronological = {"TXN-001", "TXN-002", "TXN-003", "TXN-004", "TXN-005"};

        // Non-mutating copy for display keeps the audit array intact.
        String[] newestFirst = service.reversedCopy(chronological);
        log.info(() -> "Display (newest first): " + Arrays.toString(newestFirst));
        log.info(() -> "Audit (unchanged original): " + Arrays.toString(chronological));

        // Explicit in-place reversal when mutation is acceptable.
        service.reverseInPlace(chronological);
        log.info(() -> "After in-place reverse: " + Arrays.toString(chronological));
    }
}
